#include <algorithm>
using namespace std;

using int64 = long long;
using i128 = __int128_t;

int64 extendedGcd(int64 a, int64 b, int64& x, int64& y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    int64 x1, y1;
    int64 g = extendedGcd(b, a % b, x1, y1);
    x = y1;
    y = x1 - (a / b) * y1;
    return g;
}

int64 mod(i128 value, int64 m) {
    value %= m;
    if (value < 0) value += m;
    return static_cast<int64>(value);
}

